import json,re
from pathlib import Path
rows=[]
def q(topic,title,before,after,keys,hint,why,cursor=(0,0)):
 rows.append(dict(topic=topic,title=title,before=before,after=after,cursor=list(cursor),keys=re.findall(r'<(?:Esc|Enter|C-[a-z])>|.',keys),hint=hint,why=why))
# Record transformations that combine navigation, edits and register handling.
q('Macros','Turn each key/value pair into a JSON property.','host=local\nport=8080\nmode=dev','"host": "local",\n"port": "8080",\n"mode": "dev",','qaI"<Esc>f=s": "<Esc>A",<Esc>j0q2@a','Record I", then f= and s": ", then A",. Finish with j0 and replay twice.','A delimiter motion finds each key boundary; line-end insertion handles values of different lengths.')
q('Macros','Change each Markdown heading into a bullet.','# Install\n## Configure\n### Verify','- Install\n- Configure\n- Verify','qact -<Esc>j0q2@a','Record ct followed by Space, type -, then Escape and j0.','Changing up to the first space handles a varying number of heading markers without counting them.')
q('Macros','Keep only the middle field of each CSV record.','01,Ada,admin\n02,Lin,reader\n03,Lee,editor','Ada\nLin\nLee','qadf,f,Dj0q2@a','Record df, to remove the first field; f,D removes the remaining comma and tail. End with j0.','Separate delimiter-based operations extract a field without depending on its width.')
q('Macros','Move each trailing comma to the beginning of its row.','alpha,\nbeta_long,\ngamma,',',alpha\n,beta_long\n,gamma','qa$x0Pj0q2@a','Record $x to cut the comma, 0P to put it before the row, then j0.','A one-character delete and put can move punctuation without entering Insert mode.')
q('Macros','Convert each assignment into a function call.','size=small\ncolor=blue\nmode=fast','size(small);\ncolor(blue);\nmode(fast);','qaf=r(A);<Esc>j0q2@a','Record f=r(, then A); and Escape. Finish with j0.','Character replacement preserves the value, while a separate suffix insertion closes the new syntax.')
q('Macros','Remove the enclosing quotes from each line.','"alpha"\n"beta long"\n"gamma"','alpha\nbeta long\ngamma','qa0x$xj0q2@a','Record 0x$xj0, then replay twice.','When the exact enclosing structure is guaranteed, boundary operations avoid touching spaces inside the value.')
q('Macros','Swap the first two words on every line.','red apple ripe\ngreen pear crisp\nyellow lemon tart','apple red ripe\npear green crisp\nlemon yellow tart','qadawwPj0q2@a','Record daw to cut the first word, wP to place it before the third, then j0.','Around-word deletion carries its separator, allowing the moved word to fit between existing words.')
q('Macros','Duplicate each configuration row directly below itself.','host=local\nport=8080\nmode=dev','host=local\nhost=local\nport=8080\nport=8080\nmode=dev\nmode=dev','qayypj0q2@a','Record yypj0: copy, put below, then move past the copy to the next original row.','A macro that grows the buffer must advance relative to the inserted text so it does not keep duplicating the same row.')
q('Macros','Turn each two-line name/email record into one CSV row.','Ada\nada@example.com\nLin\nlin@example.com\nLee\nlee@example.com','Ada,ada@example.com\nLin,lin@example.com\nLee,lee@example.com','qaA,<Esc>gJj0q2@a','Record A,, Escape, gJ, j0; replay twice.','Joining without added whitespace converts paired lines into a delimited record.')
q('Macros','Copy each setting name into its own quoted value.','host=""\nport=""\nmode=""','host="host"\nport="port"\nmode="mode"','qayiwf"pj0q2@a','Record yiw, f", p, then j0.','Yanking inside the macro refreshes the register on every replay, so each row supplies its own value.')
# Scope-sensitive substitutions and filtering.
q('Substitution','Collapse repeated spaces between these words to one.','alpha   beta\ngamma    delta','alpha beta\ngamma delta',':%s/  */ /g<Enter>','Use :%s/  */ /g: a space followed by space-star, replaced by one space.','A repeated-space pattern consumes a run in one match instead of removing individual spaces unpredictably.')
q('Substitution','Wrap each ERROR label in square brackets.','ERROR disk\nWARN cache\nERROR network','[ERROR] disk\nWARN cache\n[ERROR] network',':%s/^ERROR/[&]/<Enter>','Use :%s/^ERROR/[&]/.','& inserts the entire matched text into the replacement; the anchor limits wrapping to a leading label.')
q('Substitution','Replace each literal dollar sign with “USD ”.','cost=$12\nfee=$3','cost=USD 12\nfee=USD 3',r':%s/\$/USD /g<Enter>',r'Use :%s/\$/USD /g.','Escaping $ matches the currency character rather than the end-of-line anchor.')
q('Substitution','Remove the leading indentation from the pasted snippet.','  alpha\n    beta\ngamma','alpha\nbeta\ngamma',':%s/^ *//<Enter>','Use :%s/^ *//.','A start anchor restricts the whitespace match to indentation; spaces within content would remain intact.')
q('Substitution','Replace each pipe separator with a comma, leaving spaces intact.','Ada|admin|active\nLin|reader|pending','Ada,admin,active\nLin,reader,pending',':%s/[|]/,/g<Enter>','Use :%s/[|]/,/g.','A character class matches the literal pipe consistently, avoiding its alternation meaning in some regex modes.')
q('Substitution','Remove a single optional “# ” prefix on these lines.','# alpha\n# beta\ngamma','alpha\nbeta\ngamma',':%s/^# //<Enter>','Use :%s/^# //.','Lines without a match remain unchanged; substitution can clean a mixed commented/uncommented block.')
q('Substitution','Replace only two-digit revision codes with “XX”.','r=7\nr=42\nr=123','r=7\nr=XX\nr=123',':%s/=[0-9][0-9]$/=XX/<Enter>','Use :%s/=[0-9][0-9]$/=XX/.','The equals sign and end anchor constrain the entire numeric field to exactly two digits.')
q('Substitution','Remove empty parentheses at the ends of these names.','load()\nmap(item)\nsave()','load\nmap(item)\nsave',':%s/()$//<Enter>','Use :%s/()$//.','In this editor’s regex mode parentheses are grouping syntax, so literal parentheses need explicit character classes.')
rows[-1]['keys']=list(':%s/[(][)]$//')+['<Enter>'];rows[-1]['hint']='Use :%s/[(][)]$//. Character classes match the literal parentheses.';rows[-1]['why']='Literal delimiter classes and the end anchor remove only empty call suffixes, preserving calls with arguments.'
q('Global commands','Remove records whose status field is exactly “SKIP”.','KEEP build\nSKIP docs\nSKIPPING label\nSKIP lint\nKEEP test','KEEP build\nSKIPPING label\nKEEP test',':g/^SKIP /d<Enter>','Use :g/^SKIP /d, including the space after SKIP.','The field separator prevents the pattern from also matching SKIPPING.')
q('Global commands','Remove whitespace-only separator lines.','alpha\n   \nbeta\n\ngamma','alpha\nbeta\ngamma',':g/^ *$/d<Enter>','Use :g/^ *$/d.','The star allows zero or more spaces, so both empty and space-only lines match.')
# Search as a structural landmark, including direction and match preservation.
q('Search','Change the retry value on the line ending in “# production” to 5.','retries=2 # development\nretries=3 # production\nretries=1 # test','retries=2 # development\nretries=5 # production\nretries=1 # test','/production$<Enter>0f=lciw5<Esc>','Find production$, then 0f=l reaches the numeric value.','A distinctive trailing annotation can locate a record even when its key is repeated.')
q('Search','Delete the line immediately above the END marker.','keep\nremove this note\nEND\nfooter','keep\nEND\nfooter','/^END$<Enter>kdd','Search for the exact marker, move up, and delete that line.','A nearby stable marker can identify the edit location when the text to remove has no useful pattern.')
q('Search','Insert “verify();” directly before “deploy();”.','build();\ntest();\ndeploy();','build();\ntest();\nverify();\ndeploy();','/^deploy<Enter>Overify();<Esc>','Search for ^deploy, then O opens a line above.','Search plus O inserts relative to a semantic landmark without knowing its line number.')
q('Search','Delete the final standalone “temp”, leaving “template”.','temp\ntemplate\nkeep\ntemp\nEND','temp\ntemplate\nkeep\nEND','*dd','With the cursor on the first temp, * finds the next whole-word match; dd removes its line.','Whole-word search excludes template before a linewise edit.')
q('Search','Uppercase the earlier “warn” label, leaving the current one alone.','warn early\ninfo middle\nwarn late','WARN early\ninfo middle\nwarn late','#gUiw','Use # to find the preceding whole-word match, then gUiw.','Search direction controls which occurrence receives the operator.',(2,0))
q('Search','Clear the arguments of the first call after the setup section.','setup()\nrun(user, token)\nrun(cache)','setup()\nrun()\nrun(cache)','/run<Enter>f(di(','Find run, move to its parenthesis, then di(.','Searching for the function name and editing its argument object preserves other calls.')
q('Search','Change the previous chapter heading to uppercase.','chapter one\nbody\nchapter two\nbody','chapter one\nbody\nCHAPTER TWO\nbody','?^chapter<Enter>gUU','Search backward for ^chapter, then gUU uppercases its line.','An anchored backward search is useful when editing a section from somewhere inside it.',(3,0))
q('Search','Replace the last matching status with “done”.','status: queued\nstatus: running\nstatus: waiting','status: queued\nstatus: running\nstatus: done','/^status<Enter>nf:lC done<Esc>','From the first line, the search finds the second; n reaches the third. Find its colon and change the tail.','Repeated search and a local delimiter motion isolate the last field without modifying the earlier records.')
q('Search','Remove the bracketed tag from the urgent message.','[info] ready\n[urgent] restart\n[info] complete','[info] ready\nrestart\n[info] complete','/urgent<Enter>da[x','Find urgent, delete around its brackets, then x removes the leftover space.','A search result can position an enclosing text-object edit, including its delimiters.')
q('Search','Change the number after “limit” to 20, preserving the earlier version.','version=2 limit=10\nversion=3 limit=30','version=2 limit=20\nversion=3 limit=30','/limit<Enter>f=lciw20<Esc>','Search for limit, then move after its equals sign and replace the number.','Searching for the key avoids accidentally editing the first number on the same line.')
# Nested objects and targeted edits that preserve syntax.
q('Nested objects','Replace only the inner list with “ready”.','emit([old, stale], options)','emit([ready], options)','ci[ready<Esc>','Use ci[ while inside the list.','The nearest bracket object is independent of the surrounding function arguments.',(0,8))
q('Nested objects','Clear the inner object without changing the outer one.','{meta: {debug: true}, keep: 1}','{meta: {}, keep: 1}','di{','Use di{ inside the nested object.','Cursor placement chooses the nearest enclosing brace pair.',(0,10))
q('HTML objects','Replace the bold text inside the paragraph.','<p>Hello <strong>world</strong>!</p>','<p>Hello <strong>team</strong>!</p>','citteam<Esc>','Use cit with the cursor in world.','The nearest tag pair is strong, so the surrounding paragraph stays intact.',(0,19))
q('HTML objects','Remove the nested emphasis but keep the surrounding link.','<a href="/">Read<em> this</em> guide</a>','<a href="/">Read guide</a>','dat','Use dat from inside this.','Around-tag deletion removes the whole em element. The leading space inside the element is removed along with the emphasized text.',(0,21))
q('Text objects','Replace the entire URL with “/health”.','GET https://api.test/v1/users HTTP/1.1','GET /health HTTP/1.1','ciW/health<Esc>','Use ciW inside the URL.','A WORD object treats punctuation as part of the whitespace-delimited URL.',(0,12))
q('Text objects','Delete the quoted argument and its following comma-space.','send("legacy", user)','send(user)','da"xx','Use da" inside the quoted argument, then xx removes the comma and space.','Around-quotes includes the string delimiters but not its argument separator.',(0,8))
q('Text objects','Lowercase only the identifier inside parentheses.','lookup(USER_ID)','lookup(user_id)','gui(','Use gui( inside the parentheses.','Case operators accept text objects, preserving the call and its delimiters.',(0,9))
q('Text objects','Replace the backtick command while preserving the surrounding text.','Run `old --debug` now.','Run `build --release` now.','ci`build --release<Esc>','Use ci` inside the code span.','A delimiter object handles spaces within the inline command.',(0,8))
q('Text objects','Delete the first paragraph but keep the heading above it.','# Notes\n\nObsolete explanation.\nMore obsolete details.\n\nCurrent explanation.','# Notes\n\nCurrent explanation.','dap','Use dap from inside the obsolete paragraph.','The paragraph object keeps the separate heading and removes the following separator with the obsolete text.',(2,0))
q('Text objects','Replace only the final component of “user.name”.','user.name = value','user.id = value','ciwid<Esc>','Use ciw with the cursor in name.','A small-word object stops at punctuation, unlike a WORD object that would include user.name.',(0,6))
# Columns, registers, marks and composed transformations.
q('Visual block','Replace the three aligned dashes with colons.','key - value\nfoo - bar\nzip - zap','key : value\nfoo : bar\nzip : zap','<C-v>2jr:','Select the column with Ctrl+v and 2j, then r:.','A rectangular replacement changes the separator column without touching either field.',(0,4))
q('Visual block','Remove the “// ” prefixes from the three indented calls.','  // load();\n  // check();\n  // save();','  load();\n  check();\n  save();','<C-v>2j2ld','Select three columns across three lines, then d.','Starting the rectangle after indentation preserves the alignment of the uncommented code.',(0,2))
q('Visual block','Lowercase only the four-letter status column.','PASS alpha\nFAIL beta\nPASS gamma','pass alpha\nfail beta\npass gamma','<C-v>2j3lu','Select four columns across three rows, then u.','Visual-block case conversion can normalize a fixed-width field independently of its neighbors.')
q('Registers','Replace the second list with a copy of the first list’s contents.','a = [red, blue]\nb = [old]','a = [red, blue]\nb = [red, blue]','"ayi[jf[vi["ap','Yank inside the first brackets into a, select inside the second, and put a.','An explicit register separates the text you want to reuse from the text replaced by a visual put.',(0,7))
q('Registers','Swap “alpha” and “beta” while keeping the equals signs.','first=alpha\nsecond=beta','first=beta\nsecond=alpha','"ayiwjf=l"byiwviw"ap k0f=lviw"bp','Save alpha in a and beta in b, then replace each word using the opposite register.','Two named registers let you exchange values without losing either one.',(0,7))
rows[-1]['keys']=re.findall(r'<(?:Esc|Enter|C-[a-z])>|.','"ayiwjf=l"byiwviw"apk0f=lviw"bp')
q('Registers','Copy the first two words to the end of the line.','red blue green','red blue green red blue','y2wA <Esc>px','Yank two words, append a space, then put and remove the trailing separator.','Wordwise yanks can include a trailing space; a precise target may require cleaning that separator.')
q('Marks','Bring the two-line note under the heading.','Notes\nbody\nseparator\nline one\nline two\nEND','Notes\nline one\nline two\nbody\nseparator\nEND','maG2k2dd\'ap','Mark the heading, cut two lines above END, return with \'a, and put.','A named destination survives the line-number changes caused by cutting a block.')
q('Composed edits','Convert the array brackets to parentheses without changing the contents.','[alpha, beta]','(alpha, beta)','%r)0r(','Jump to the matching bracket with %, replace it, then replace the opening bracket.','Matching-pair motion is safer than counting characters to reach the closing delimiter.')
q('Composed edits','Replace both quoted arguments with empty strings.','copy("source", "destination")','copy("", "")','di"f,f"ldi"','Delete inside the first quotes, find the comma and next opening quote, then delete inside the second.','After shrinking the first value, use delimiters to find the second instead of its old column.',(0,8))
q('Composed edits','Indent the inner two statements and add semicolons.','if (ready) {\nload()\nsave()\n}','if (ready) {\n  load();\n  save();\n}','Vj>A;<Esc>j.','Select the two lines and shift right; append a semicolon and repeat on the other line.','A block operation and dot repeat can handle independent formatting changes without retyping the statements.',(1,0))
assert len(rows)==50,len(rows)
