Path('content').mkdir(exist_ok=True)
Path('content/quiz-pack-191-240.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
p=Path('dist/course.js');s=p.read_text();mark='// Practice expansion: exercises 191–240.'
